-- =========================================================================
-- BLOCK 2: Upsert all 31 events from businessleadersofcharlotte.com
-- Paste this whole file into the Supabase SQL editor (new query) and click "Run".
-- Idempotent — uses events.ics_uid unique constraint; safe to re-run later.
-- =========================================================================

on conflict (ics_uid) do update set
  title            = excluded.title,
  description      = excluded.description,
  starts_at        = excluded.starts_at,
  ends_at          = excluded.ends_at,
  location_name    = excluded.location_name,
  location_address = excluded.location_address,
  chapter          = excluded.chapter,
  kind             = excluded.kind,
  public_visible   = excluded.public_visible;

-- Verify counts.
select count(*) as total_events,
       count(*) filter (where starts_at > now()) as upcoming
from public.events;
